import "server-only";

import radioData from "@/data/radio.json";
import type { RadioData, RadioSource, RadioStation } from "@/lib/radio/types";

/**
 * `data/radio.json` is generated by `npm run radio:sync`.
 *
 * The player never talks to GeetGanga directly: it only streams the mp3 URLs
 * captured at build time, so the site stays fast and we never hammer the
 * source. Re-run the sync when you want the stations refreshed.
 */
const data = radioData as unknown as RadioData;

export const radioSource: RadioSource = data.source;
export const radioGeneratedAt: string = data.generated_at;

/** Stations with at least one playable track, in sync order. */
export function getRadioStations(): RadioStation[] {
  return data.stations.filter((station) => station.tracks.length > 0);
}
